tokens.value:
oklch(
      from var(--button-color-solid) calc(l * 0.75) c h
    )

oklch(
      from var(--button-color-solid) l c h / 0.35
    )

var(
      --vds-color-primary-solid-active,
      oklch(from var(--button-color-solid) calc(l * 0.85) c h)
    )

var(
      --vds-color-success-solid-active,
      oklch(from var(--button-color-solid) calc(l * 0.85) c h)
    )

var(
      --vds-color-warning-solid-active,
      oklch(from var(--button-color-solid) calc(l * 0.85) c h)
    )

var(
      --vds-color-danger-solid-active,
      oklch(from var(--button-color-solid) calc(l * 0.85) c h)
    )

var(
      --vds-color-info-solid-active,
      oklch(from var(--button-color-solid) calc(l * 0.85) c h)
    )

var(
      --vds-color-accent-solid-active,
      oklch(from var(--button-color-solid) calc(l * 0.85) c h)
    )

min(
      var(--card-radius),
      var(--card-parent-radius, var(--card-radius)),
      max(var(--card-nested-radius, var(--card-radius)), var(--vds-radius-xs, 0px))
    )

0 -1px 0 var(--data-table-border-color),
      0 -12px 24px -18px color-mix(
        in oklch,
        var(--data-table-cell-color),
        transparent 88%
      )

color-mix(
      in oklab,
      var(--vds-color-ring, var(--vds-color-primary-9, #6366f1)) 18%,
      transparent
    )

linear-gradient(
      180deg,
      color-mix(in oklch, var(--drawer-surface), white 4%),
      var(--drawer-surface)
    )

inset 0 1px 0
      color-mix(
        in oklch,
        var(--vds-color-surface, #ffffff) 72%,
        transparent
      )

var(
      --vds-radius-inset,
      max(
        0px,
        calc(
          var(--tabs-list-radius) - var(--tabs-list-border-width) -
            var(--tabs-list-padding-block)
        )
      )
    )

var(--vds-overlay-shadow, var(
      --vds-toast-shadow,
      0 10px 38px -10px color-mix(in oklch, black 28%, transparent),
      0 10px 20px -15px color-mix(in oklch, black 18%, transparent)
    ))

var(--vds-overlay-shadow, var(
      --vds-toast-shadow-hover,
      0 10px 38px -10px color-mix(in oklch, black 28%, transparent),
      0 10px 20px -15px color-mix(in oklch, black 18%, transparent),
      0 8px 30px -8px color-mix(in oklch, black 30%, transparent)
    ))

